  '{"copy":{"header":{"brand_name":"The Grand Appartement","brand_meta":"Le Chesnay · Versailles","logo_alt":"Logo The Grand Appartement"},"hero":{"eyebrow":"Appartement entier proche du château de Versailles","title":"Séjournez au calme, sans compromis sur le confort","text":"Un appartement de 54 m² dans un immeuble de charme, pensé pour 4 voyageurs, avec arrivée autonome, espace télétravail, équipements famille et accès rapide à Versailles comme à Paris.","image_alt":"Salon lumineux du Grand Appartement"},"platform_stats":{"eyebrow":"Confiance voyageurs","title":"Très bien noté sur les plateformes","intro":"Des séjours réussis, un logement soigné et un accueil apprécié."},"host":{"caption":"Michaël · votre hôte","eyebrow":"Votre hôte","title":"Une adresse familiale à laquelle nous sommes attachés, proposée avec soin","quote":"Un ancien chez-nous que nous ouvrons avec attention — pour que vous vous sentiez attendus, pas simplement logés.","intro_1":"Je m''appelle Michaël et je suis originaire du Chesnay. J''aime rencontrer de nouvelles personnes, écouter de la musique et voyager avec ma famille.","intro_2":"Nous revenons régulièrement dans cet appartement avec nos enfants et nous avons gardé l’envie d’en faire un lieu simple, chaleureux et fiable pour les voyageurs.","image_alt":"Photo de Michaël, hôte du Grand Appartement","cta":"Faire une réservation"},"spaces":{"eyebrow":"Nos espaces coup de coeur","title":"Du salon à la chambre : un appartement à vivre comme chez vous","intro":"Vivre le quotidien, bien dormir, cuisiner sur place, travailler un moment si besoin et savourer Versailles depuis un cadre calme : chaque espace a sa raison d’être"},"benefits":{"eyebrow":"Les atouts du logement","title":"Un séjour simple à organiser, agréable à vivre et qui s’adapte à votre rythme"},"location":{"eyebrow":"Quartier & environnement","title":"Un emplacement stratégique entre Versailles, commerces et Paris","intro":"Quartier résidentiel calme et verdoyant du Chesnay, à deux pas de Versailles : idéal pour conjuguer visites culturelles, vie quotidienne et déplacements professionnels.","lead":"Vous logez à proximité du château, des commerces de bouche, des marchés locaux et des grands axes vers Paris. Un cadre paisible, sans être isolé."},"visual":{"eyebrow":"Explorer le lieu","title":"Quelques images pour vous projeter avant votre arrivée","intro":"L’appartement convient aussi bien à un week-end autour du château qu’à un séjour plus long, en famille ou pour le travail.","gallery_cta_eyebrow":"Galerie complète","gallery_cta_title":"Voir tous les espaces","gallery_cta_text":"Parcourez chaque pièce en images, de jour comme de nuit.","gallery_cta_action":"Explorer la galerie ▸"},"pricing":{"eyebrow":"Tarifs","title":"Des repères simples avant de réserver","intro":"En réservant en direct avec nous, vous évitez les commissions des plateformes et les frais cachés souvent ajoutés au panier : le prix annoncé correspond au prix payé. Les nuitées et les remises à partir de 7 ou 28 nuits ci-dessous servent de repère ; le détail se finalise avec vous, simplement et sans surprise"},"amenities":{"eyebrow":"Équipements","title":"Un cadre chaleureux avec tout le nécessaire pour un séjour serein","intro":"Wifi fibre, cuisine complète, linge fourni, équipements bébé et sécurité : tout est pensé pour éviter les mauvaises surprises"},"reviews":{"eyebrow":"Retours voyageurs","title":"Des expériences très positives autour du calme, de la propreté et de l’accueil"},"rules":{"eyebrow":"Règlement intérieur","title":"Des règles simples pour un séjour serein","intro":"Quelques principes essentiels pour préserver le calme du voisinage et le bon état du logement, pour vous comme pour les voyageurs suivants.","check_in_label":"Arrivée","check_in_time":"À partir de 17 h","check_out_label":"Départ","check_out_time":"Avant 11 h"},"booking":{"price_recap_note":"Montant calculé à partir des tarifs affichés sur cette page (nuits, remises long séjour, nombre de voyageurs adultes et enfants). Hors taxes de séjour. Le paiement par carte interviendra à l’étape suivante.","price_recap_note_payment":"Montant calculé à partir des tarifs affichés sur cette page (nuits, remises long séjour, nombre de voyageurs adultes et enfants). Hors taxes de séjour. Règlement par carte sécurisé ci-dessous."}},"email":{"access_lines":["Boîte à clés sécurisée — arrivée autonome, sans rendez-vous à l’immeuble.","Repère pratique : place de la Loi (bus), à quelques minutes à pied.","Parking possible dans la rue et les rues adjacentes (selon créneaux et zone).","Assistance à distance en français et en anglais si besoin pendant le séjour."]},"featured_spaces":[{"title":"Salle à manger & télétravail","text":"Table extensible, belle hauteur sous plafond et coin bureau pour un séjour aussi agréable que pratique.","image":"/gallery/dining-room.jpeg","tag":"Vie quotidienne","gallery_category_id":"espace-repas"},{"title":"Chambre principale","text":"Une ambiance calme et reposante avec lit double confortable et stores occultants.","image":"/gallery/bedroom.jpeg","tag":"Repos","gallery_category_id":"chambre-principale"},{"title":"Cuisine équipée","text":"Induction, four, lave-vaisselle, lave-linge et tout le nécessaire pour cuisiner sur place.","image":"/gallery/kitchen.jpeg","tag":"Autonomie","gallery_category_id":"cuisine"}],"space_gallery_categories":[{"id":"salon","title":"Salon","description":"Grand salon lumineux pour se détendre, regarder un film ou recevoir jusqu’à quatre personnes confortablement.","images":["/gallery/espaces/salon/01.jpeg","/gallery/espaces/salon/02.jpeg"]},{"id":"cuisine","title":"Cuisine","description":"Cuisine entièrement équipée : induction, four, lave-vaisselle et lave-linge pour cuisiner sur place sans contrainte.","images":["/gallery/espaces/cuisine/01.jpeg","/gallery/espaces/cuisine/02.jpeg","/gallery/espaces/cuisine/03.jpeg","/gallery/espaces/cuisine/04.jpeg"]},{"id":"espace-repas","title":"Espace repas","description":"Table extensible et belle hauteur sous plafond : un vrai coin repas, aussi pratique pour le télétravail que pour les dîners.","images":["/gallery/espaces/espace-repas/01.jpeg","/gallery/espaces/espace-repas/02.jpeg","/gallery/espaces/espace-repas/03.jpeg"]},{"id":"chambre-principale","title":"Chambre principale","description":"Chambre calme avec lit double, literie confortable et stores occultants pour bien récupérer après une journée à Versailles.","images":["/gallery/espaces/chambre-principale/01.jpeg","/gallery/espaces/chambre-principale/02.jpeg"]},{"id":"chambre-secondaire","title":"Chambre secondaire","description":"Seconde chambre cosy, idéale pour les enfants ou pour accueillir un invité, avec rangements pratiques.","images":["/gallery/espaces/chambre-secondaire/01.jpeg","/gallery/espaces/chambre-secondaire/02.jpeg","/gallery/espaces/chambre-secondaire/03.jpeg"]},{"id":"salle-de-bain","title":"Salle de bain","description":"Salle de bain claire et fonctionnelle, avec douche et tout le nécessaire pour un séjour sans surprise.","images":["/gallery/espaces/salle-de-bain/01.jpeg","/gallery/espaces/salle-de-bain/02.jpeg"]},{"id":"espace-travail","title":"Espace de travail","description":"Coin bureau discret avec connexion fibre : idéal pour une visio ou une demi-journée de travail au calme.","images":["/gallery/espaces/espace-travail/01.jpeg"]},{"id":"exterieur","title":"Extérieur","description":"Espace extérieur pour prendre l’air, un café le matin ou une pause entre deux visites du château.","images":["/gallery/espaces/exterieur/01.jpeg","/gallery/espaces/exterieur/02.jpeg","/gallery/espaces/exterieur/03.jpeg"]},{"id":"jeux-enfants","title":"Jeux et équipements pour enfants","description":"Équipements pensés pour les familles : jeux et matériel adapté pour que les plus jeunes se sentent chez eux.","images":["/gallery/espaces/jeux-enfants/01.jpeg","/gallery/espaces/jeux-enfants/02.jpeg"]}],"benefit_cards":[{"icon":"calendar","title":"Longs séjours avantageux","text":"10% de remise dès 7 nuits et 20% de remise dès 28 nuits."},{"icon":"family","title":"Pensé pour les familles","text":"Lit parapluie, chaise haute, jouets, livres et plusieurs équipements bébé sont disponibles."},{"icon":"key","title":"Arrivée simple","text":"Boîte à clés sécurisée, accès autonome et assistance à distance en français et en anglais."},{"icon":"parking","title":"Parking pratique","text":"Stationnement dans la rue et rues adjacentes, avec créneaux gratuits selon la zone et la période."}],"visual_cards":[{"title":"Séjour convertible","text":"Le salon devient une chambre supplémentaire pour accueillir jusqu’à 4 voyageurs.","image":"/gallery/hero-salon.jpeg","gallery_category_id":"salon"},{"title":"Espace de travail","text":"Un coin bureau confortable avec fibre wifi, idéal pour les séjours professionnels.","image":"/gallery/workspace.jpeg","gallery_category_id":"espace-travail"},{"title":"Immeuble de charme","text":"Une adresse pleine de caractère dans un quartier résidentiel calme et bien connecté.","image":"/gallery/facade.jpeg","gallery_category_id":"exterieur"},{"title":"Vue cour & verdure","text":"Une atmosphère paisible qui contraste agréablement avec la proximité de Versailles.","image":"/gallery/courtyard.jpeg","gallery_category_id":"exterieur"}],"neighborhood_highlights":[{"icon":"castle","title":"Château de Versailles","text":"À proximité immédiate pour une visite à pied ou en transports, sans repartir de loin."},{"icon":"pin","title":"Place de la Loi","text":"Point de repère pour l’accès : desservie par les bus, idéale pour vous orienter à l’arrivée."},{"icon":"mall","title":"Parly 2","text":"Grand centre commercial (Westfield) pour les courses, restaurants et sorties faciles."},{"icon":"train","title":"Versailles & Paris","text":"Trois gares de Versailles vers Saint-Lazare, Montparnasse et Austerlitz pour rejoindre Paris."},{"icon":"market","title":"Commerces & marchés","text":"Boulangeries, supermarchés et pharmacies à proximité. Marchés à Versailles (mar., ven., dim. matin) et au Chesnay (sam. matin)."},{"icon":"mobility","title":"Stationnement & mobilité","text":"Places dans la rue et rues adjacentes. Stationnement payant à Versailles en semaine, gratuit le dimanche, en août et les jours fériés. Bornes de recharge véhicules électriques à environ 5 min à pied (rue de Versailles)."}],"house_rules":[{"title":"Non-fumeur","text":"Le logement est strictement non-fumeur (cigarettes et vapoteuses)."},{"title":"Pas de fêtes","text":"Les fêtes et événements sont interdits par respect pour le voisinage."},{"title":"Pas d’animaux","text":"Les animaux ne sont pas acceptés dans le logement."},{"title":"Calme requis","text":"Les voyageurs doivent respecter le calme entre 22 h et 8 h."},{"title":"Pas de tournage","text":"La photographie commerciale et les tournages ne sont pas autorisés."},{"title":"Respect du lieu","text":"Merci de traiter l’appartement et la copropriété comme votre propre chez-vous."},{"title":"Escaliers","text":"Les voyageurs doivent monter des escaliers pour accéder au logement."},{"title":"Environnement urbain","text":"Le logement est situé en zone urbaine : des nuisances sonores sont possibles pendant le séjour."}],"platform_links":[{"id":"airbnb","name":"Airbnb","rating":"4,97 / 5","stars":"★★★★★","label":"Superhôte","logo":"/platforms/platform_airbnb.png","url":"https://airbnb.fr/h/louisxiv"},{"id":"booking","name":"Booking","rating":"8,5 / 10","stars":"★★★★☆","label":"Très bien noté","logo":"/platforms/platform_booking.png","url":"https://www.booking.com/hotel/fr/appartement-proche-chateau-de-versailles-le-chesnay-rocquencourt.fr.html"},{"id":"abritel","name":"Abritel","rating":"10 / 10","stars":"★★★★★","label":"Excellente note","logo":"/platforms/platform_abritel.png","url":"https://www.abritel.fr/location-vacances/p2608338"}],"reviews":[{"id":"nike-2026-04","author":"Nike","date":"Avril 2026","rating":5,"quote":"L’appartement est TOP ! Michael est très sympa disponible également. Tout été nickel."},{"id":"solenne-2026-04","author":"Solenne","date":"Avril 2026","rating":5,"quote":"nous avons passé une nuit chez Michael pour aller visiter le château de Versailles. Le logement est à 30 minutes à pied, nous avons même laissé la voiture sur la journée (16 euros de parcmètre). logement propre et tres bien équipé Michael a été très réactif, notamment pour nous signaler un oubli dans l''appartement. je recommande"},{"id":"alison-2026-04","author":"Alison","date":"Avril 2026","rating":5,"quote":"L''appartement était spacieux et extrêmement propre et bien rangé. C''était très calme la nuit. Le parking extérieur a bien fonctionné, car il était gratuit le week-end et il était relativement facile de trouver une place. Il était situé à proximité des commerces et restaurants locaux. Nous avons apprécié notre séjour."},{"id":"marlene-2026-04","author":"Marlène","date":"Avril 2026","rating":5,"quote":"honnêtement rien a redire ,tout etait parfait ,Michael est super comme hôte."},{"id":"amy-2026-03","author":"Amy","date":"Mars 2026","rating":5,"quote":"Logement idéal où séjourner, tout a été facile à trouver et pour l''arrivée ; Michael a été réactif et serviable"},{"id":"veronique-2026-03","author":"Veronique","date":"Mars 2026","rating":5,"quote":"Michaël fut un hôte particulièrement compréhensif et réactif et s''est adapté avec gentillesse aux changements liés à l''organisation de notre séjour professionnel. En arrêt maladie pendant cette période, mon collègue a séjourné seul dans le logement. Il a beaucoup apprécié la situation (proche commerces, château, accès facile), le calme, la propreté et l''équipement des lieux (bonne literie, accessoires cuisine parfaits). Tout est pensé pour offrir un agréable séjour. Nous recommandons donc vivement ce gîte. Merci Michaël"},{"id":"amelie-2025-10","author":"Amélie","date":"Octobre 2025","rating":5,"quote":"Mickaël est un hôte soucieux du bien être des personnes qu''il reçoit, les explications données à notre arrivée étaient très claires, l''appartement est spacieux, l''immeuble est paisible, nous avons tout fait à pied sur Versailles. Nous recommandons le logement de Mickaël pour son authenticité et pour la réactivité de son hôte."},{"id":"aurelie-2025-10","author":"Aurélie","date":"Octobre 2025","rating":5,"quote":"Séjour très agréable, le logement était impeccable et conforme à la description. L’appartement était spacieux, un vrai plus pour les enfants. Merci beaucoup."},{"id":"pierre-eloi-2025-06","author":"Pierre-Eloi Bérénice","date":"Juin 2025","rating":5,"quote":"Nous avons été merveilleusement bien accueilli par Michael qui a été un hôte attentif aux détails et très communicant. Il a été aux petits soins pour que nous ne manquions de rien notamment pour nos 2 petits. Logement très bien tenu et qui correspondait à ce que nous avions imaginé. Nous reviendrons avec plaisir si l’occasion nous en est donné. Nous recommandons vivement."}],"amenity_catalog":[{"id":"equipements","title":"Équipements","items":[{"id":"caches-prises","icon":"plug","name":"Caches-prises"},{"id":"cafe","icon":"coffee","name":"Café"},{"id":"chaise-haute","icon":"highchair","name":"Chaise haute","description":"Standalone • Toujours dans le logement."},{"id":"chauffage","icon":"heat","name":"Chauffage","description":"Équipement utilisé pour chauffer un logement."},{"id":"cheminee","icon":"fireplace","name":"Cheminée"},{"id":"cintres","icon":"hanger","name":"Cintres"},{"id":"congelateur","icon":"freezer","name":"Congélateur"},{"id":"cuisine","icon":"kitchen","name":"Cuisine","description":"Un espace pour cuisiner des repas comprenant au moins un réfrigérateur, un four et une surface de cuisson."},{"id":"cuisiniere","icon":"stove","name":"Cuisinière","description":"Other • Induction • 4 feux."},{"id":"detecteur-fumee","icon":"smoke","name":"Détecteur de fumée","description":"Un appareil qui alerte les occupants d''un logement lorsqu''il détecte de la fumée (vérifiez la législation locale : celle-ci peut exiger la présence d''un détecteur de fumée en état de marche dans votre logement)."},{"id":"detecteur-co","icon":"co","name":"Détecteur de monoxyde de carbone","description":"Un appareil qui alerte les occupants d''un logement en cas de détection d''un taux dangereux de monoxyde de carbone (vérifiez la législation locale : celle-ci peut exiger la présence d''un détecteur de monoxyde de carbone en état de marche dans votre logement)."},{"id":"eau-chaude","icon":"water","name":"Eau chaude","description":"L''eau du lavabo et de la douche ou de la baignoire est assez chaude pour se laver."},{"id":"entree-privee","icon":"door","name":"Entrée privée","description":"Une entrée réservée aux voyageurs."},{"id":"rangement-vetements","icon":"closet","name":"Espace de rangement pour les vêtements","description":"Armoire."},{"id":"bureau","icon":"desk","name":"Espace de travail dédié","description":"Privé."},{"id":"fer","icon":"iron","name":"Fer à repasser"},{"id":"four","icon":"oven","name":"Four","description":"Simple."},{"id":"micro-ondes","icon":"microwave","name":"Four à micro-ondes"},{"id":"grille-pain","icon":"toaster","name":"Grille-pain"},{"id":"grilles-fenetre","icon":"window","name":"Grilles de fenêtre"},{"id":"jardin","icon":"garden","name":"Jardin","description":"Public ou partagé."},{"id":"lave-linge","icon":"washer","name":"Lave-linge","description":"Une machine pour laver les vêtements sales."},{"id":"lave-vaisselle","icon":"dishwasher","name":"Lave-vaisselle"},{"id":"laverie","icon":"laundry","name":"Laverie automatique à proximité"},{"id":"linge","icon":"bedding","name":"Linge de lit","description":"Coton."},{"id":"lit-parapluie","icon":"crib","name":"Lit parapluie","description":"Lit parapluie • Toujours dans le logement • Stores occultants dans la pièce • Compris dans votre séjour."},{"id":"livres","icon":"books","name":"Livres et de quoi lire"},{"id":"jouets","icon":"toys","name":"Livres et jouets pour enfants","description":"0 à 2 ans, 2 à 5 ans."},{"id":"machine-cafe","icon":"coffee-machine","name":"Machine à café","description":"Cafetière filtre."},{"id":"nettoyage","icon":"cleaning","name":"Produits de nettoyage"},{"id":"frigo","icon":"fridge","name":"Réfrigérateur"},{"id":"borne-ve","icon":"ev","name":"Station de recharge pour véhicules électriques","description":"Une station où les voyageurs peuvent recharger leur véhicule électrique sur place."},{"id":"parking-gratuit","icon":"parking","name":"Stationnement gratuit dans la rue","description":"Stationnement gratuit disponible dans une rue voisine."},{"id":"parking-payant","icon":"parking","name":"Stationnement payant sur place","description":"Stationnement payant disponible au logement."},{"id":"parking-rue","icon":"parking","name":"Stationnement payant à l''extérieur de la propriété","description":"Stationnement dans la rue."},{"id":"stores","icon":"blinds","name":"Stores occultants"},{"id":"audio","icon":"audio","name":"Système audio","description":"Bluetooth."},{"id":"seche-cheveux","icon":"hairdryer","name":"Sèche-cheveux"},{"id":"seche-linge","icon":"dryer","name":"Sèche-linge","description":"Une machine pour sécher les vêtements mouillés."},{"id":"table-a-langer","icon":"changing-table","name":"Table à langer","description":"Toujours dans le logement."},{"id":"table","icon":"dining","name":"Table à manger","description":"10 places."},{"id":"secours","icon":"firstaid","name":"Trousse de premiers secours"},{"id":"vaisselle","icon":"dishes","name":"Vaisselle et couverts","description":"Assiettes, bols, tasses, couverts et autres ustensiles."},{"id":"verres","icon":"wine","name":"Verres à vin"},{"id":"wifi","icon":"wifi","name":"Wifi","description":"Technologie sans fil permettant aux appareils de se connecter à internet."},{"id":"base-cuisine","icon":"basics","name":"Équipements de cuisine de base","description":"Casseroles et poêles, huile, sel et poivre"}]}],"amenity_preview_sections":[{"id":"preview-1","title":"Équipements","items":[{"id":"caches-prises","icon":"plug","name":"Caches-prises"},{"id":"cafe","icon":"coffee","name":"Café"},{"id":"chaise-haute","icon":"highchair","name":"Chaise haute","description":"Standalone • Toujours dans le logement."},{"id":"chauffage","icon":"heat","name":"Chauffage","description":"Équipement utilisé pour chauffer un logement."},{"id":"cheminee","icon":"fireplace","name":"Cheminée"}],"hasMore":true},{"id":"preview-2","title":"Équipements (suite)","items":[{"id":"entree-privee","icon":"door","name":"Entrée privée","description":"Une entrée réservée aux voyageurs."},{"id":"rangement-vetements","icon":"closet","name":"Espace de rangement pour les vêtements","description":"Armoire."},{"id":"bureau","icon":"desk","name":"Espace de travail dédié","description":"Privé."},{"id":"fer","icon":"iron","name":"Fer à repasser"},{"id":"four","icon":"oven","name":"Four","description":"Simple."}],"hasMore":true},{"id":"preview-3","title":"Équipements (suite)","items":[{"id":"laverie","icon":"laundry","name":"Laverie automatique à proximité"},{"id":"linge","icon":"bedding","name":"Linge de lit","description":"Coton."},{"id":"lit-parapluie","icon":"crib","name":"Lit parapluie","description":"Lit parapluie • Toujours dans le logement • Stores occultants dans la pièce • Compris dans votre séjour."},{"id":"livres","icon":"books","name":"Livres et de quoi lire"},{"id":"jouets","icon":"toys","name":"Livres et jouets pour enfants","description":"0 à 2 ans, 2 à 5 ans."}],"hasMore":true},{"id":"preview-4","title":"Équipements (suite)","items":[{"id":"stores","icon":"blinds","name":"Stores occultants"},{"id":"audio","icon":"audio","name":"Système audio","description":"Bluetooth."},{"id":"seche-cheveux","icon":"hairdryer","name":"Sèche-cheveux"},{"id":"seche-linge","icon":"dryer","name":"Sèche-linge","description":"Une machine pour sécher les vêtements mouillés."},{"id":"table-a-langer","icon":"changing-table","name":"Table à langer","description":"Toujours dans le logement."}],"hasMore":true}]}'::jsonb
